import json
from fractions import Fraction
from collections import defaultdict

def load_json(path):
    with open(path) as f:
        return json.load(f)

# Complete symbolic analysis for C(2)
gamma2 = load_json('<home>/notebook/git/thm01-R/thm01-R-sonnet46-A/data/C_1_gamma.json')
cob2 = load_json('<home>/notebook/git/thm01-R/thm01-R-sonnet46-A/data/C_1_coboundary.json')

# Build symbolic gamma: (X,Y,Z) -> {gb_key: coeff}
sym_gamma = defaultdict(dict)
for e in gamma2['inhomogeneous_deformation']['gamma_coefficients']:
    key = (e['X'], e['Y'], e['Z'])
    sym_gamma[key][e['gb_key']] = Fraction(e['coeff'])

# Build coboundary: (X,Y,Z) -> {phi: coeff}
cob_map = defaultdict(dict)
for e in cob2['coboundary']['delta_f_entries']:
    key = (e['X'], e['Y'], e['Z'])
    for pt in e['phi_terms']:
        cob_map[key][pt['phi']] = Fraction(pt['coeff'])

# Find all (X,Y,Z) in gamma with Z != K where coboundary is absent
print("=== Obstruction set: gamma terms with no coboundary counterpart ===")
obstruction_constraints = defaultdict(Fraction)  # gb_key -> sum of constraints

for key, gb_terms in sym_gamma.items():
    X, Y, Z = key
    if Z == 'K':
        # K-terms: always obstruction
        for gb_key, coeff in gb_terms.items():
            print(f"  K-obstruction: gamma({X}, {Y}, K) = {coeff}*{gb_key}")
    elif key not in cob_map:
        # g-component not in coboundary: the sum must be 0
        print(f"  g-obstruction: gamma({X}, {Y}, {Z}) = ", end="")
        parts = [f"{coeff}*{gb_key}" for gb_key, coeff in gb_terms.items()]
        print(" + ".join(parts), "must be 0")
        for gb_key, coeff in gb_terms.items():
            obstruction_constraints[gb_key] += coeff  # accumulate (informal)

print()
print("=== Summary of obstruction constraints ===")
# Each individual K-term gives: coeff * gb_key = 0 (each independently)
# Collect unique constraints
unique_k_constraints = {}  # gb_key -> set of required-zero conditions
for key, gb_terms in sym_gamma.items():
    X, Y, Z = key
    if Z == 'K':
        for gb_key, coeff in gb_terms.items():
            unique_k_constraints[gb_key] = True

print("From K-terms: the following gb parameters must be 0:")
for gb_key in sorted(unique_k_constraints.keys()):
    print(f"  {gb_key} = 0")

unique_g_constraints = {}
for key, gb_terms in sym_gamma.items():
    X, Y, Z = key
    if Z != 'K' and key not in cob_map:
        for gb_key, coeff in gb_terms.items():
            unique_g_constraints[gb_key] = True

print("\nFrom g-component obstructions: the following gb parameters must be 0:")
for gb_key in sorted(unique_g_constraints.keys()):
    print(f"  {gb_key} = 0")

print()
# Check which gb params are unconstrained
all_gb = {p['label'] for p in gamma2['inhomogeneous_deformation']['gb_matrix']['parameters']}
constrained = set(unique_k_constraints.keys()) | set(unique_g_constraints.keys())
unconstrained = all_gb - constrained
print(f"All gb params: {sorted(all_gb)}")
print(f"Constrained to 0: {sorted(constrained)}")
print(f"Unconstrained: {sorted(unconstrained)}")
print()
print("CONCLUSION: The deformation is trivial IFF ALL gb = 0.")
EOF

